const videoLibrary = Object.values(videos);
const progressKey = "buildit-course-progress-v1";
const notesKey = "buildit-course-notes-v1";
const pageContent = document.querySelector("#page-content");
const lessonList = document.querySelector("#lesson-list");
const searchInput = document.querySelector("#lesson-search");
const searchResults = document.querySelector("#search-results");
let completed = readProgress();
let learningNotes = readNotes();

function readProgress() {
  try {
    const saved = JSON.parse(localStorage.getItem(progressKey) || "[]");
    return Array.isArray(saved) ? saved.filter((number) => Number.isInteger(number) && number >= 1 && number <= 24) : [];
  } catch {
    return [];
  }
}

function readNotes() {
  try {
    const saved = JSON.parse(localStorage.getItem(notesKey) || "{}");
    return saved && typeof saved === "object" && !Array.isArray(saved) ? saved : {};
  } catch {
    return {};
  }
}

function saveProgress() {
  localStorage.setItem(progressKey, JSON.stringify(completed));
  updateProgress();
}

function updateProgress() {
  const count = completed.length;
  document.querySelector("#progress-count").textContent = `${count} of 24`;
  document.querySelector("#sidebar-progress-bar").style.width = `${(count / 24) * 100}%`;
  document.querySelector("#sidebar-progress-bar").setAttribute("aria-valuenow", String(count));
}

function renderNavigation(filter = "") {
  const query = filter.trim().toLowerCase();
  lessonList.innerHTML = lessons.map((lesson, index) => ({ lesson, number: index + 1 }))
    .filter(({ lesson, number }) => !query || `${lesson.title} ${lesson.group} ${lesson.lead} ${lesson.priority} hour ${number}`.toLowerCase().includes(query))
    .map(({ lesson, number }) => `<li><a class="lesson-link" href="#lesson-${String(number).padStart(2, "0")}" data-lesson="${number}"><span class="lesson-number">${String(number).padStart(2, "0")}</span><span>${lesson.title}</span>${completed.includes(number) ? '<span class="lesson-check" aria-label="Complete">✓</span>' : ""}</a></li>`)
    .join("");
}

function renderOverview() {
  const nextIncomplete = lessons.findIndex((_, index) => !completed.includes(index + 1));
  const startNumber = nextIncomplete < 0 ? 1 : nextIncomplete + 1;
  const groups = [
    ["Hours 1–4", "Web and JavaScript", "Trace a request, make a page, and learn the JavaScript patterns React uses."],
    ["Hours 5–6", "TypeScript", "Describe data and functions; narrow types and type API responses."],
    ["Hours 7–14", "React frontend", "Build components, forms, routes, styles, and API-backed pages."],
    ["Hours 15–19", "Server and data", "Build an Express REST API and persist user-owned records in PostgreSQL."],
    ["Hours 20–24", "Production and review", "Add authentication, security, GitHub, deployment, debugging, and a final challenge."],
  ];
  pageContent.innerHTML = `
    <section class="hero">
      <div class="hero-content">
        <p class="hero-kicker">A practical 24-hour learning path</p>
        <h1>From first page<br />to <em>full-stack app.</em></h1>
        <p class="hero-copy">Build a task and project manager while learning how a modern web app fits together. Short lessons, real code, useful breaks, and a working product at the end.</p>
        <div class="hero-actions"><a class="button" href="#lesson-${String(startNumber).padStart(2, "0")}">Continue learning <span aria-hidden="true">→</span></a><a class="button secondary" href="#videos">Browse video tutorials</a></div>
      </div>
    </section>

    <div class="section-head"><div><span class="section-label">The app we will build</span><h2>A place for projects and tasks</h2><p>Start with one working screen. Add capability when the lesson needs it.</p></div><span class="priority must">Core project</span></div>
    <div class="stack-grid">
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">UI</span><span class="priority must">Must know</span></div><h3>React + TypeScript</h3><p>Build reusable, typed browser screens.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">V</span><span class="priority must">Must know</span></div><h3>Vite + React Router</h3><p>Run the frontend and move between pages.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">API</span><span class="priority must">Must know</span></div><h3>Node.js + Express</h3><p>Run the server and build the API.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">DB</span><span class="priority must">Must know</span></div><h3>PostgreSQL</h3><p>Store projects and tasks for later.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">AUTH</span><span class="priority should">Should know</span></div><h3>Supabase Auth</h3><p>Use managed sign-in and database tools where they simplify setup.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">GH</span><span class="priority must">Must know</span></div><h3>Git + GitHub</h3><p>Track changes and host the source repository.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">WEB</span><span class="priority must">Must know</span></div><h3>Frontend + API hosting</h3><p>Publish the browser app and server online.</p></article>
      <article class="stack-item"><div class="stack-top"><span class="stack-icon">HTML</span><span class="priority must">Must know</span></div><h3>HTML + CSS + JavaScript</h3><p>Understand the building blocks beneath React.</p></article>
    </div>

    <div class="section-head"><div><span class="section-label">Follow one task</span><h2>How the pieces work together</h2><p>React runs in the browser. Express runs on a server. PostgreSQL stores persistent information.</p></div></div>
    <div class="architecture" aria-label="Browser frontend communicates with the server API, which reads and writes the database">
      <div class="arch-node"><strong>Browser</strong><span>React shows pages, handles forms, and sends HTTP requests.</span></div><span class="arch-arrow" aria-hidden="true">⇄</span>
      <div class="arch-node"><strong>Server</strong><span>Express validates requests, checks identity and ownership, and returns JSON.</span></div><span class="arch-arrow" aria-hidden="true">⇄</span>
      <div class="arch-node"><strong>Database</strong><span>PostgreSQL stores users, projects, and tasks beyond a refresh.</span></div>
    </div>
    <div class="lifecycle"><strong>Full request lifecycle:</strong> click in the browser → React sends a request → API validates and authorizes → database saves or reads → API returns JSON → React updates the screen. Git tracks changes, GitHub hosts the repository, and deployment platforms serve the production app.</div>
    <div class="course-notes compact-notes">
      <article class="note-card"><h3>Client rendering and SSR</h3><p>Our Vite + React app uses client-side rendering: the browser runs React and builds the interface. SSR means a server sends already-rendered page HTML. SSR can help with search visibility or initial page delivery; frameworks such as Next.js become useful when those needs justify the added architecture. We will not add SSR to this beginner project.</p></article>
      <article class="note-card"><h3>Keep the first architecture small</h3><p>We will use REST and local React state first. Supabase can simplify hosted PostgreSQL and authentication. We will not introduce Next.js, Docker, Kubernetes, GraphQL, Redux, or another advanced tool unless a real project need appears.</p></article>
    </div>

    <div class="section-head"><div><span class="section-label">Course map</span><h2>Twenty-four focused hours</h2><p>Each page is one hour of guided building. Take short breaks and spend substantial time writing, running, debugging, and explaining code.</p></div><div class="priority-key"><span class="priority must">Must know</span><span class="priority should">Should know</span><span class="priority later">Learn later</span></div></div>
    <div class="timeline">${groups.map((group, index) => `<a class="phase-card" href="#lesson-${String([1, 5, 7, 15, 20][index]).padStart(2, "0")}"><span class="phase-hours">${group[0]}</span><h3>${group[1]}</h3><p>${group[2]}</p><span class="phase-arrow" aria-hidden="true">↗</span></a>`).join("")}</div>

    <div class="section-head" id="videos"><div><span class="section-label">Watch alongside the lessons</span><h2>Video tutorials</h2><p>Use these as visual companions. Pause and build with me instead of watching for hours without practice.</p></div></div>
    <div class="video-library">${videoLibrary.map((video) => videoCard(video)).join("")}</div>
    <p class="resource-note">Videos are visual companions, and some older lessons use earlier tool versions. Check the <a href="https://react.dev/learn" target="_blank" rel="noopener noreferrer">React documentation</a>, <a href="https://vite.dev/guide/" target="_blank" rel="noopener noreferrer">Vite guide</a>, and <a href="https://supabase.com/docs/guides/auth/quickstarts/react" target="_blank" rel="noopener noreferrer">current Supabase React auth guide</a> when commands or APIs may have changed.</p>

    <div class="section-head"><div><span class="section-label">A repeatable lesson rhythm</span><h2>How we work together</h2><p>Each lesson follows the same teaching sequence, then pauses for your answers.</p></div></div>
    <div class="course-notes">
      <article class="note-card"><h3>Every lesson includes</h3><ul><li>Plain-English explanation, why it matters, and an analogy</li><li>A tiny example and code walkthrough</li><li>How it fits the project and the exact file location</li><li>Run steps, likely mistakes, one mini-exercise, and two or three checkpoint questions</li><li>A progress update for completed topics, weak areas, exercises, and what remains</li></ul></article>
      <article class="note-card"><h3>Learning priorities</h3><p><strong>Must know:</strong> required to build and deploy core CRUD. <strong>Should know:</strong> useful for reliable real applications. <strong>Learn later:</strong> valuable topics outside our first project. Twenty-four hours is an intensive introduction, not mastery.</p><p class="note-follow-up">We will not move to the next major lesson until you have answered the checkpoint. If a concept is unclear, we will explain it another way and try another example.</p></article>
    </div>

    <div class="section-head"><div><span class="section-label">Keep the code findable</span><h2>Simple project organization</h2><p>Only add folders when code has a clear reason to live there.</p></div></div>
    <div class="structure"><pre aria-label="Example frontend folder structure">frontend/src/
  components/  reusable UI pieces
  pages/       route-level screens
  layouts/     shared page frame
  hooks/       shared React behavior
  services/    API and auth calls
  types/       shared TypeScript shapes
  assets/      local images and icons</pre><pre aria-label="Example backend folder structure">server/src/
  routes/      URL and method mapping
  controllers/ request/response handling
  middleware/  shared request checks
  services/    application rules
  db/          connection and migrations
  types/       backend data shapes</pre></div>

    <div class="section-head"><div><span class="section-label">At the finish line</span><h2>What you will demonstrate</h2></div></div>
    <div class="course-notes">
      <article class="note-card"><h3>Working application</h3><ul><li>Responsive home page, navigation, multiple routes, and not-found page</li><li>Registration, login, logout, and protected user-specific data</li><li>Project/task CRUD, forms, search, filter, sort, and status updates</li><li>Database persistence, loading/error/empty/success messages</li><li>GitHub repository, public deployment URL, and professional README</li></ul></article>
      <article class="note-card"><h3>Final practical challenge</h3><p>Add a due-date filter with minimal hints. Explain your component, types, request flow, database ownership rule, and how you debugged it. I’ll review your work, explain mistakes, and make a 30-day learning plan from the areas that felt weakest.</p><p class="note-follow-up">If we run short on time, protect core CRUD, the connected database, GitHub, and deployment. Treat advanced features as optional.</p></article>
    </div>
    <div class="overview-end"><span>Progress is stored in this browser on this device.</span><span>Next: Hour 1 · How the web works</span></div>`;
}

function videoCard(video, compact = false) {
  return `<article class="video-card" data-video-card="${video.id}"><div class="video-card-head"><span class="video-label">Video tutorial</span><h3>${video.title}</h3><p>${video.channel}</p></div><div class="video-player" data-player="${video.id}" hidden></div><div class="video-actions"><button class="button small" type="button" data-load-video="${video.id}">▶ Play here</button><a class="button small ${compact ? "secondary" : "secondary"}" href="${video.url}" target="_blank" rel="noopener noreferrer">YouTube ↗</a></div></article>`;
}

const sectionTitles = ["The simple explanation", "Why it matters", "A real-world analogy", "A tiny example", "Code walkthrough", "Build it into our project", "File location", "Run and test", "Common mistakes", "Mini-exercise", "Checkpoint", "Progress update"];

function renderLesson(number) {
  const lesson = lessons[number - 1];
  if (!lesson) return renderOverview();
  const isDone = completed.includes(number);
  const details = [lesson.simple, lesson.why, lesson.analogy, lesson.example, lesson.walkthrough, lesson.build, lesson.files, lesson.run, lesson.mistakes, lesson.exercise, lesson.checkpoint, lesson.progress];
  const sections = details.map((detail, index) => {
    const content = Array.isArray(detail) ? `<ul>${detail.map((line) => `<li>${line}</li>`).join("")}</ul>` : `<p>${detail}</p>`;
    return `<section class="lesson-section" id="lesson-section-${index + 1}"><h2><span class="section-index">${String(index + 1).padStart(2, "0")}</span>${sectionTitles[index]}</h2>${content}</section>`;
  }).join("");
  const video = videos[lesson.video];
  const extraVideo = lesson.extraVideo ? videos[lesson.extraVideo] : null;
  pageContent.innerHTML = `
    <div class="lesson-topline"><span class="lesson-number-label">Hour ${String(number).padStart(2, "0")} / 24 · ${lesson.group}</span><span class="priority ${lesson.priority === "Must know" ? "must" : "should"}">${lesson.priority}</span></div>
    <header class="lesson-heading"><h1>${lesson.title}</h1><p class="lead">${lesson.lead}</p><div class="lesson-meta"><span class="meta-chip">~50 min learning + practice</span><span class="meta-chip">Pause and explain it back</span></div></header>
    <div class="lesson-layout"><div><div class="lesson-sections">${sections}</div>
      <nav class="lesson-pager" aria-label="Lesson pages"><button class="button secondary" type="button" data-go="${number - 1}" ${number === 1 ? "disabled" : ""}>← Previous</button><span class="pager-center">${number} / 24</span><button class="button" type="button" data-go="${number + 1}" ${number === 24 ? "disabled" : ""}>Next lesson →</button></nav>
    </div><aside class="lesson-aside" aria-label="Lesson tools"><section class="aside-card"><span class="priority ${lesson.priority === "Must know" ? "must" : "should"}">${lesson.priority}</span><h2>Lesson progress</h2><p>${isDone ? "Marked complete in this browser." : "Mark complete after the exercise and checkpoint make sense."}</p><button class="button small lesson-progress-button ${isDone ? "done" : ""}" type="button" data-complete="${number}">${isDone ? "✓ Completed" : "Mark complete"}</button></section><section class="aside-card"><h2>Learning journal</h2><p>Note a tricky topic, an error to revisit, or the next small practice step.</p><label for="learning-note-${number}">My note for this hour</label><textarea class="learning-note" id="learning-note-${number}" placeholder="What felt unclear? What should we practice again?"></textarea><button class="button small lesson-progress-button" type="button" data-save-note="${number}">Save note</button><p class="save-note-status" id="note-status-${number}" role="status"></p></section>${videoCard(video, true)}${extraVideo ? videoCard(extraVideo, true) : ""}</aside></div>`;
  const noteField = document.querySelector(`#learning-note-${number}`);
  noteField.value = typeof learningNotes[number] === "string" ? learningNotes[number] : "";
  document.querySelector("#breadcrumb-current").textContent = `Hour ${String(number).padStart(2, "0")} · ${lesson.title}`;
  document.querySelector("[data-overview-link]").classList.remove("active");
  document.querySelectorAll(".lesson-link").forEach((link) => link.classList.toggle("active", Number(link.dataset.lesson) === number));
  document.title = `Hour ${number}: ${lesson.title} — Build It`;
}

function route() {
  const hash = location.hash.slice(1);
  const lessonMatch = hash.match(/^lesson-(\d{2})$/);
  if (lessonMatch) renderLesson(Number(lessonMatch[1]));
  else {
    renderOverview();
    document.querySelector("#breadcrumb-current").textContent = "Overview";
    document.querySelector("[data-overview-link]").classList.add("active");
    document.querySelectorAll(".lesson-link").forEach((link) => link.classList.remove("active"));
    document.title = "Build It — 24-hour full-stack course";
  }
  closeSidebar();
  if (searchInput.value.trim()) runSearch(searchInput.value);
}

function runSearch(query) {
  const normalized = query.trim().toLowerCase();
  renderNavigation(normalized);
  if (!normalized) {
    searchResults.hidden = true;
    searchResults.innerHTML = "";
    return;
  }
  const matches = lessons.map((lesson, index) => ({ lesson, number: index + 1 }))
    .filter(({ lesson, number }) => `${lesson.title} ${lesson.group} ${lesson.lead} ${lesson.simple} ${lesson.priority} hour ${number}`.toLowerCase().includes(normalized)).slice(0, 7);
  searchResults.innerHTML = matches.length ? matches.map(({ lesson, number }) => `<a role="option" href="#lesson-${String(number).padStart(2, "0")}"><strong>Hour ${String(number).padStart(2, "0")} · ${lesson.title}</strong><span>${lesson.group} — ${lesson.lead}</span></a>`).join("") : '<div class="no-results" role="option">No matching lessons. Try a topic such as “forms”, “database”, or “React”.</div>';
  searchResults.hidden = false;
}

function closeSidebar() {
  document.querySelector("#course-sidebar").classList.remove("open");
  document.querySelector("#sidebar-scrim").hidden = true;
  document.querySelector("#mobile-menu-button").setAttribute("aria-expanded", "false");
}

function loadVideo(id, trigger) {
  const player = document.querySelector(`[data-player="${id}"]`);
  if (!player) return;
  player.hidden = false;
  player.innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?rel=0" title="Video tutorial player" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`;
  trigger.textContent = "Video loaded";
  trigger.disabled = true;
}

lessonList.addEventListener("click", (event) => {
  if (event.target.closest("a")) searchResults.hidden = true;
});
searchResults.addEventListener("click", (event) => {
  if (event.target.closest("a")) {
    searchInput.value = "";
    renderNavigation();
    searchResults.hidden = true;
  }
});
document.addEventListener("click", (event) => {
  const go = event.target.closest("[data-go]");
  const mark = event.target.closest("[data-complete]");
  const saveNote = event.target.closest("[data-save-note]");
  const load = event.target.closest("[data-load-video]");
  if (go && !go.disabled) location.hash = `lesson-${String(Number(go.dataset.go)).padStart(2, "0")}`;
  if (mark) {
    const number = Number(mark.dataset.complete);
    completed = completed.includes(number) ? completed.filter((item) => item !== number) : [...completed, number].sort((a, b) => a - b);
    saveProgress();
    renderNavigation(searchInput.value);
    renderLesson(number);
  }
  if (saveNote) {
    const number = Number(saveNote.dataset.saveNote);
    learningNotes[number] = document.querySelector(`#learning-note-${number}`).value;
    try {
      localStorage.setItem(notesKey, JSON.stringify(learningNotes));
      document.querySelector(`#note-status-${number}`).textContent = "Note saved on this device.";
    } catch {
      document.querySelector(`#note-status-${number}`).textContent = "Could not save. Browser storage may be unavailable.";
    }
  }
  if (load) loadVideo(load.dataset.loadVideo, load);
  if (!event.target.closest(".search-wrap")) searchResults.hidden = true;
});

document.querySelector("[data-overview-link]").addEventListener("click", () => { searchResults.hidden = true; });
window.addEventListener("hashchange", route);
searchInput.addEventListener("input", () => runSearch(searchInput.value));
searchInput.addEventListener("keydown", (event) => {
  if (event.key === "Enter") {
    const firstResult = searchResults.querySelector("a");
    if (firstResult) location.hash = firstResult.getAttribute("href");
  }
  if (event.key === "Escape") { searchInput.value = ""; runSearch(""); searchResults.hidden = true; }
});
document.addEventListener("keydown", (event) => {
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
    event.preventDefault();
    searchInput.focus();
  }
});
document.querySelector("#mobile-menu-button").addEventListener("click", (event) => {
  const sidebar = document.querySelector("#course-sidebar");
  const isOpen = sidebar.classList.toggle("open");
  document.querySelector("#sidebar-scrim").hidden = !isOpen;
  event.currentTarget.setAttribute("aria-expanded", String(isOpen));
});
document.querySelector("#sidebar-scrim").addEventListener("click", closeSidebar);

renderNavigation();
updateProgress();
route();
